    "text": "[Questão 012 - Prova PDF]\nTexto para as questões de 012 a 015: A redação de documentos oficiais deve primar pela clareza, concisão e impessoalidade. Diferente da literatura ou do jornalismo, as comunicações da Administração Pública não toleram arroubos retóricos, subjetivismos ou ambiguidades. O destinatário de um ofício ou relatório policial necessita compreender o fato narrado de forma imediata e inequívoca. A clareza decorre do emprego de termos simples e de uma estrutura sintática direta. A concisão, por sua vez, consiste em transmitir o máximo de informações com o mínimo de palavras, eliminando excessos burocráticos que engessam a máquina estatal.\n\nCom base na leitura do texto, a concisão na redação oficial é definida como:",
