    "subject": "Língua Portuguesa",
    "subjectId": "portugues",
    "topic": "Língua Portuguesa",
    "difficulty": "Médio",
    "text": "[Questão 029 - Prova PDF]\nAssinale a opção em que o termo sublinhado funciona como aposto explicativo:",
