    "subjectId": "portugues",
    "topic": "Língua Portuguesa",
    "difficulty": "Médio",
    "text": "[Questão 032 - Prova PDF]\nNo enunciado \"As investigações policiais, as quais duraram meses, resultaram na desarticulação da quadrilha\" , a oração sublinhada introduz uma:",
