    "topic": "Língua Portuguesa",
    "difficulty": "Médio",
    "text": "[Questão 037 - Prova PDF]\nAssinale a opção que apresenta incorreção quanto ao emprego do hífen de acordo com o Novo Acordo Ortográfico:",
    "options": [
      "A) Infraestrutura.",
      "B) Antiterrotista.",
      "C) Contra-ataque.",
      "D) Micro-organismo.",
      "E) Supre-estrutural."
    ],
