    "difficulty": "Difícil",
    "text": "[Questão 105 - Prova PDF]\nUma equipe tática de capturas da PCMA é composta por 8 oficiais investigadores e 4 delegados de carreira. Para uma missão sigilosa em Imperatriz, necessita-se formar uma comissão operacional contendo exatamente 3 oficiais investigadores e 2 delegados. O número total de maneiras distintas de se estruturar essa comissão é igual a:",
