    "text": "[Questão 106 - Prova PDF]\nNo cofre de evidências de uma delegacia especializada, há 6 armas do tipo revólver e 4 armas do tipo pistola. Se o investigador plantonista retirar aleatoriamente 2 armas consecutivas desse cofre, sem reposição, a probabilidade de que ambas as armas retiradas sejam pistolas é igual a:",
