    "difficulty": "Médio",
    "text": "[Questão 107 - Prova PDF]\nDois investigadores, Carlos e Marcos, emitem as seguintes declarações a respeito de uma operação. Carlos diz: \"Todos os suspeitos fugiram\" . No dia seguinte, a perícia provou que a declaração de Carlos era falsa. Desse modo, a afirmação que é logicamente verdadeira é:",
