    "text": "[Questão 108 - Prova PDF]\nConsidere três proposições simples: P (O réu confessa), Q (O advogado orienta a defesa) e R (O juiz concede a liberdade). Se a proposição composta \"Se P e não Q, então R\" possui valor lógico FALSO, conclui-se que os valores lógicos das proposições P , Q e R são, respectivamente:",
