    "text": "[Questão 109 - Prova PDF]\nA respeito da lógica dos diagramas de conjuntos, considere as seguintes premissas: \"Todos os policiais civis são dedicados\" e \"Alguns maranhenses são policiais civis\" . A partir dessas premissas, conclui-se de forma necessária que:",
