    "commentary": "Gabarito B: Analisando as falas de Bruno e Caio, percebe-se que elas são contraditórias (se Bruno fala a verdade, Caio mente, e vice- versa). Como apenas um deles fala a verdade, o mentiroso restante deve ser André. Se a fala de André (\"Bruno cometeu o crime\") é falsa, Bruno é inocente. Se Bruno é inocente, a fala de Bruno (\"Caio cometeu o crime\") é falsa. Logo, Caio é o culpado, o que torna a fala de Caio verdadeira. O culpado é Caio e quem diz a verdade é Caio. (Nota técnica de correção: O culpado é Caio e quem diz a verdade é Caio. A alternativa C traz Caio e André. Avaliando os rótulos, se Caio diz a verdade, Bruno cometeu o crime é falso. André cometeu o crime? Se André for o culpado: André diz Bruno cometeu = F . Bruno diz Caio cometeu = F . Caio diz Bruno mentiu = V . Se André for o culpado, apenas Caio fala a verdade. Portanto, Culpado = André, Verdade = Caio. Alternativa correta: D)."
