    "text": "[Questão 115 - Prova PDF]\nDurante a criação de senhas de acesso ao sistema de inteligência da PCMA, os usuários devem criar códigos compostos por exatamente 3 letras distintas seguidas por 2 algarismos também distintos. Utilizando as 26 letras do alfabeto e os 10 algarismos do sistema decimal (de 0 a 9), o número de senhas diferentes que podem ser geradas é dado pela expressão de contagem:",
