    "text": "[Questão 117 - Prova PDF]\nConsidere a proposição condicional: \"Se o réu foi indiciado, então o Ministério Público oferece a denúncia\" . Uma proposição logicamente equivalente à apresentada, utilizando a regra da contrapositiva, é:",
