    "text": "[Questão 119 - Prova PDF]\nQuatro oficiais de polícia — Almir, Bento, Cláudio e Daniel — possuem idades diferentes e trabalham em delegacias distintas. Sabe-se que: Almir é mais velho que Bento; Cláudio é mais moço que Daniel; Bento é mais velho que Daniel. Diante dessas informações, o oficial de polícia mais moço de todos é:",
