    "text": "[Questão 123 - Prova PDF]\nEm uma prateleira da delegacia de Balsas, há 5 volumes de manuais de direito penal e 3 volumes de manuais de direito processual penal. De quantas maneiras diferentes esses 8 livros podem ser organizados lado a lado na prateleira, de modo que os livros de direito processual penal permaneçam sempre juntos entre si?",
