    "text": "[Questão 124 - Prova PDF]\nA probabilidade de um atirador de elite da polícia civil acertar o alvo em um disparo operacional é de 80%. Se ele efetuar 2 disparos independentes e consecutivos, a probabilidade de que ele acerte o alvo em pelo menos um dos disparos é igual a:",
