    "text": "[Questão 125 - Prova PDF]\nDois conjuntos de dados criminais, X e Y , possuem elementos em comum. Sabe-se que o número de elementos do conjunto X é igual a 30, o número de elementos de Y é igual a 25 e o número de elementos da união de X com Y é igual a 45. O número de elementos que pertencem exclusivamente à interseção de X e Y é igual a:",
