    "text": "[Questão 126 - Prova PDF]\nConsidere que as seguintes premissas de um argumento sejam verdadeiras: \"Se o suspeito comprou a passagem, então ele viajou\" e \"O suspeito não viajou\" . A partir dessas premissas, a conclusão válida para esse argumento é:",
