    "text": "[Questão 134 - Prova PDF]\nEm uma reunião operacional na delegacia regional, estão presentes 5 investigadores e 5 escrivães. Deseja-se formar uma equipe de plantão contendo exatamente 2 investigadores e 2 escrivães. De quantas maneiras diferentes essa equipe de plantão pode ser escalada?",
