    "text": "[Questão 136 - Prova PDF]\nConsidere a proposição composta P: \"Se a perícia for robusta e a testemunha colaborar, então o réu é condenado\" . A tabela-verdade associada a essa proposição apresenta um valor lógico FALSO em apenas uma situação. Essa situação ocorre quando:",
