      "C) 81% da variação total da variável dependente Y é explicada pela variação da variável independente X por meio da reta de regressão.",
      "D) O modelo falhou em explicar 81% do comportamento dos dados observados.",
      "E) O coeficiente angular da reta cresce na razão estocástica de 81% por unidade."
