    "text": "[Questão 234 - Prova PDF]\nInversamente ao comportamento de picos agudos, o achatamento relativo define outra categoria de curtose. Uma distribuição que possui caudas leves e um formato mais achatado e espalhado no topo do que a curva normal classifica-se como:",
