    "difficulty": "Difícil",
    "text": "[Questão 237 - Prova PDF]\nEm um conjunto de dados brutos ordenados em ordem crescente, a medida posicional que divide a série exatamente em duas partes iguais, deixando 50% das observações abaixo dela e 50% acima dela, configura a:",
