    "topic": "Estatística",
    "difficulty": "Médio",
    "text": "[Questão 238 - Prova PDF]\nA respeito dos quartis de uma distribuição descritiva de dados, sabe-se que o segundo quartil (Q2) coincide perfeitamente com o valor da:",
