    "commentary": "Gabarito C: O histograma é composto por barras verticais coladas e adjacentes (sem espaços entre elas, para demonstrar continuidade das classes). A base de cada retângulo assenta-se sobre a amplitude do intervalo de classe na reta horizontal, e a altura espelha a frequência observada."
