    "correctIndex": 1,
    "commentary": "Gabarito B: Pelo comportamento das variâncias amostrais e do erro padrão (𝜎/√𝑛), aumentar o tamanho da amostra (n) injeta mais informação no modelo estatístico, contraindo as margens de erro e aproximando as estimativas amostrais dos verdadeiros parâmetros da população."
