    "commentary": "Gabarito C: A amostragem por julgamento (ou intencional) apoia-se na expertise do pesquisador. Ele escolhe a dedo quais elementos farão parte da amostra por ter a convicção técnica de que aqueles casos específicos carregam as características fundamentais necessárias para explicar o fenômeno."
