    "text": "[Questão 242 - Prova PDF]\nOutro método de amostragem não- probabilística inicia-se selecionando um pequeno grupo de indivíduos que possuem características raras do objeto de estudo, solicitando-se a estes que indiquem novos contatos de sua rede social com perfil semelhante para participar da pesquisa, criando uma cadeia progressiva de indicações. Esse método é a:",
