    "text": "[Questão 268 - Prova PDF]\n(Geografia do Maranhão) A hidrografia do Maranhão é rica e desempenha um papel econômico vital na irrigação e transporte. O rio que nasce no sul do estado, corta extensas áreas produtoras de grãos, deságua no Oceano Atlântico abrindo-se em um estuário na Baía de São Marcos e banha a capital São Luís em sua foz é o Rio:",
