    "text": "[Questão 270 - Prova PDF]\n(Geografia do Maranhão) A vegetação do Maranhão apresenta uma formação vegetal de transição (ecótono) endêmica de extrema importância econômica para as comunidades extrativistas locais, caracterizada pela presença massiva das palmeiras de babaçu e carnaúba. Essa formação vegetal denomina- se:",
