    "text": "[Questão 271 - Prova PDF]\n(Geografia do Maranhão) O clima do Maranhão sofre a influência direta da dinâmica de massas de ar equatoriais e tropicais ao longo do ano. Na porção ocidental e norte do estado, o clima classifica-se predominantemente como:",
