    "text": "[Questão 272 - Prova PDF]\n(Geografia do Maranhão) A Baixada Maranhense é uma sub-região geográfica singular protegida por convenções internacionais de zonas úmidas (Convenção de Ramsar). Ambientalmente e morfologicamente, a Baixada Maranhense caracteriza-se por:",
