    "text": "[Questão 273 - Prova PDF]\n(Geografia do Maranhão) Os Lençóis Maranhenses constituem um dos principais polos ecoturisticos do Brasil e do mundo, tendo recebido o título de Patrimônio Mundial da Humanidade pela UNESCO. A dinâmica geomorfológica que explica a formação da paisagem dos Lençóis baseia-se na:",
