    "text": "[Questão 276 - Prova PDF]\n(Geografia do Maranhão) O Complexo Portuário do Itaqui, localizado em São Luís, ostenta importância geopolítica e econômica estratégica para o Brasil. A principal vantagem comparativa natural do Porto de Itaqui que o diferencia de outros portos nacionais é:",
