    "text": "[Questão 279 - Prova PDF]\n(Geografia do Maranhão) O Maranhão enfrenta desafios socioeconômicos estruturais refletidos em seus indicadores demográficos. Apesar do crescimento econômico do agronegócio e da mineração, o estado apresenta historicamente:",
