    "text": "[Questão 280 - Prova PDF]\n(Geografia do Maranhão) O Rio Mearim é famoso por um fenômeno natural hidrodinâmico espetacular que ocorre em sua foz durante as luas cheia e nova, atraindo surfistas e pesquisadores internacionais. Esse fenômeno de encontro das águas do rio com a maré enchente denomina-se:",
