    "text": "[Questão 281 - Prova PDF]\n(Geografia do Maranhão) O Centro de Lançamento de Alcântara (CLA), localizado na Baía de São Marcos, confere ao Maranhão posição de destaque na engenharia aeroespacial global. A escolha tática de Alcântara para sediar a base de foguetes justifica-se por sua:",
