    "text": "[Questão 282 - Prova PDF]\n(Geografia do Maranhão) O processo de urbanização da Região Metropolitana da Grande São Luís envolve quatro municípios conurbados localizados na Ilha de São Luís. Assinale a alternativa que apresenta um município que não integra a Ilha de São Luís:",
