    "text": "[Questão 284 - Prova PDF]\n(Geografia do Maranhão) Os solos do bioma Cerrado no sul do Maranhão, embora profundos e planos (ideais para a mecanização), exigem correção química corretiva prévia para o plantio devido às suas características pedológicas naturais. Esses solos são predominantemente:",
