    "text": "[Questão 351 - Prova PDF]\n(Organização Administrativa) A Polícia Civil do Estado do Maranhão (PCMA) integra o aparelho estatal do Poder Executivo estadual. Do ponto de vista da organização da Administração Pública, a PCMA constitui um órgão público que resulta do processo de:",
