    "difficulty": "Médio",
    "text": "[Questão 353 - Prova PDF]\n(Agentes Públicos) Um Oficial Investigador da PCMA, aprovado em concurso público e em estágio probatório, cometeu uma infração funcional grave catalogada no estatuto da corporação. A respeito do instituto do estágio probatório e da aquisição da estabilidade no serviço público, assinale a opção correta de acordo com o artigo 41 da CF/88:",
