      "B) O servidor público em estágio probatório adquire estabilidade após três anos de efetivo exercício, condicionado à avaliação especial de desempenho por comissão instituída para esse fim.",
      "C) Servidores em comissão ou ocupantes de funções de confiança adquirem estabilidade após cinco anos de exercício contínuo.",
      "D) A demissão de servidor estável só pode ocorrer mediante decreto unilateral e discricionário do Governador do Estado.",
